1	// Promotes a Kodely user to ADMIN so they can reach /admin — or demotes one.
2	// Deliberately NOT an HTTP endpoint — a self-serve "become admin" API would
3	// be a privilege-escalation hole. Run this directly on the box instead:
4	//   node scripts/promote-admin.mjs someone@example.com
5	//   node scripts/promote-admin.mjs someone@example.com --revoke
6	//
7	// Run it against the database you mean: DATABASE_URL differs per environment,
8	// so promoting yourself locally does nothing on staging or prod.
9	import { PrismaClient } from "@prisma/client";
10	
11	const email = process.argv[2]?.trim().toLowerCase();
12	const revoke = process.argv.includes("--revoke");
13	
14	if (!email) {
15	  console.error("Usage: node scripts/promote-admin.mjs <email> [--revoke]");
16	  process.exit(1);
17	}
18	
19	const db = new PrismaClient();
20	try {
21	  const user = await db.user.findUnique({ where: { email } });
22	  if (!user) {
23	    console.error(`No user with email ${email}`);
24	    process.exit(1);
25	  }
26	
27	  const role = revoke ? "CUSTOMER" : "ADMIN";
28	  if (user.role === role) {
29	    console.log(`${email} is already ${role}. Nothing to do.`);
30	  } else {
31	    await db.user.update({ where: { id: user.id }, data: { role } });
32	    console.log(`${email}: ${user.role} -> ${role}`);
33	  }
34	
35	  // Always print the resulting roster. Who can see cost, margin and customer
36	  // prompts should never be a thing you have to go and look up separately.
37	  const admins = await db.user.findMany({
38	    where: { role: "ADMIN" },
39	    select: { email: true },
40	    orderBy: { email: "asc" },
41	  });
42	  console.log(`\nAdmins now (${admins.length}): ${admins.map((a) => a.email).join(", ") || "none"}`);
43	} finally {
44	  await db.$disconnect();
45	}
