1	import { PrismaClient } from "@prisma/client";
2	import { readFileSync } from "node:fs";
3	
4	const db = new PrismaClient();
5	const posts = JSON.parse(readFileSync("./seo-batch1.json", "utf8"));
6	
7	for (const p of posts) {
8	  await db.blogPost.upsert({
9	    where: { slug: p.slug },
10	    create: {
11	      slug: p.slug,
12	      title: p.title,
13	      metaDescription: p.metaDescription,
14	      category: p.category,
15	      targetKeyword: p.targetKeyword,
16	      bodyHtml: p.bodyHtml,
17	    },
18	    update: {
19	      title: p.title,
20	      metaDescription: p.metaDescription,
21	      category: p.category,
22	      targetKeyword: p.targetKeyword,
23	      bodyHtml: p.bodyHtml,
24	    },
25	  });
26	  console.log("inserted:", p.slug);
