1	// One-time setup: installs the foundation's dependencies into a shared
2	// location every project build reuses via a symlink (see lib/build-site.ts).
3	// This is the ONLY npm install that ever runs for site generation — keep this
4	// package.json byte-identical to the one in lib/foundation.ts.
5	import { mkdir, writeFile } from "node:fs/promises";
6	import { execFileSync } from "node:child_process";
7	
8	const FOUNDATION_DIR = process.env.KODELY_FOUNDATION_DIR ?? "/home/kodely/kodely-foundation";
9	
10	const PACKAGE_JSON = {
11	  name: "kodely-site",
12	  private: true,
13	  version: "0.0.0",
14	  type: "module",
15	  scripts: { build: "vite build" },
16	  dependencies: {
17	    react: "^19.2.8",
18	    "react-dom": "^19.2.8",
19	  },
20	  devDependencies: {
21	    "@tailwindcss/vite": "^4.3.3",
22	    "@vitejs/plugin-react": "^6.0.5",
23	    tailwindcss: "^4.3.3",
24	    typescript: "^7.0.2",
25	    vite: "^8.2.1",
26	  },
27	};
28	
29	await mkdir(FOUNDATION_DIR, { recursive: true });
30	await writeFile(`${FOUNDATION_DIR}/package.json`, JSON.stringify(PACKAGE_JSON, null, 2));
31	
32	console.log(`Installing foundation dependencies into ${FOUNDATION_DIR} ...`);
33	// npm is npm.cmd on Windows, and since CVE-2024-27980 Node refuses to spawn
34	// a .cmd without a shell (EINVAL). Both args here are constants — nothing
35	// user-supplied reaches the shell — so shell:true is safe.
36	const isWindows = process.platform === "win32";
37	execFileSync(isWindows ? "npm.cmd" : "npm", ["install"], {
38	  cwd: FOUNDATION_DIR,
39	  stdio: "inherit",
40	  shell: isWindows,
41	});
42	console.log("Done.");
