1	// Bootstraps the app's real TypeScript modules into a plain Node script.
2	//
3	// The eval harness deliberately calls the SAME code path production uses —
4	// `runAgent` from lib/agent.ts and `buildSite` from lib/build-site.ts — rather
5	// than a reimplementation, because a scoreboard that measures a copy of the
6	// generator measures nothing. Getting those .ts modules loadable from a .mjs
7	// script under bare Node (no bundler, no ts-node, no new dependencies) needs
8	// three fixes, all of them here:
9	//
10	//   1. Node 22.6+/24 strips TypeScript types natively, but its ESM resolver
11	//      still demands full specifiers. lib/agent.ts imports "./models" with no
12	//      extension, which Node cannot resolve on its own.
13	//   2. Route handlers use the "@/..." tsconfig path alias, which only a
14	//      bundler understands.
15	//   3. buildSite reads KODELY_FOUNDATION_DIR from the environment and silently
16	//      falls back to a Linux path ("/home/kodely/kodely-foundation") when it is
17	//      missing — which surfaces as a misleading "Cannot find module" from vite
18	//      rather than "your env is not loaded". Next.js loads .env for you; a bare
19	//      node script does not, so we parse it here.
20	//
21	// The resolve hook is scoped to files inside the repo and outside
22	// node_modules, so it can never interfere with how dependencies (many of them
23	// CommonJS) resolve their own imports.
24	
25	import { registerHooks } from "node:module";
26	import { existsSync, readFileSync } from "node:fs";
27	import { fileURLToPath, pathToFileURL } from "node:url";
28	import path from "node:path";
29	
30	/** Repo root: this file lives at <root>/scripts/eval/loader.mjs. */
31	export const ROOT = path.resolve(import.meta.dirname, "..", "..");
32	
33	const ROOT_POSIX = ROOT.replace(/\\/g, "/");
34	const CANDIDATE_EXTENSIONS = [".ts", ".tsx", ".mts", ".js", ".mjs", "/index.ts", "/index.tsx"];
35	
36	let hooksRegistered = false;
37	let envLoaded = false;
38	
39	/**
40	 * Minimal .env parser. Deliberately not dotenv: the constraint for this harness
41	 * is Node built-ins only, and the file is a handful of plain KEY=VALUE lines.
42	 * Existing process.env values win, so `KODELY_ENGINE=api node run.mjs` still
43	 * overrides the file.
44	 */
45	export function loadEnv({ quiet = false } = {}) {
46	  if (envLoaded) return;
47	  envLoaded = true;
48	
49	  const envPath = path.join(ROOT, ".env");
50	  if (!existsSync(envPath)) {
51	    if (!quiet) console.warn(`[eval] no .env at ${envPath} — relying on the ambient environment`);
52	  } else {
53	    for (const rawLine of readFileSync(envPath, "utf8").split(/\r?\n/)) {
54	      const line = rawLine.trim();
55	      if (!line || line.startsWith("#")) continue;
56	      const eq = line.indexOf("=");
57	      if (eq === -1) continue;
58	      const key = line.slice(0, eq).trim();
59	      let value = line.slice(eq + 1).trim();
60	      if (
61	        (value.startsWith('"') && value.endsWith('"') && value.length > 1) ||
62	        (value.startsWith("'") && value.endsWith("'") && value.length > 1)
63	      ) {
64	        value = value.slice(1, -1);
65	      }
66	      if (!(key in process.env)) process.env[key] = value;
67	    }
68	  }
69	
70	  // The failure this guard exists for: without it, every single build in the
71	  // suite fails with a vite "Cannot find module" that points nowhere near the
72	  // real cause. Fail loudly and early instead of 28 times, confusingly.
73	  const foundation = process.env.KODELY_FOUNDATION_DIR;
74	  if (!foundation) {
75	    throw new Error(
76	      "KODELY_FOUNDATION_DIR is not set. buildSite would fall back to the Linux " +
77	        "default path and every build would fail. Set it in .env (it points at the " +
78	        "checkout produced by scripts/install-foundation.mjs).",
79	    );
80	  }
81	  if (!existsSync(path.join(foundation, "node_modules"))) {
82	    throw new Error(
83	      `KODELY_FOUNDATION_DIR=${foundation} has no node_modules. ` +
84	        "Run `node scripts/install-foundation.mjs` first — buildSite symlinks that tree " +
85	        "instead of running npm install per generation.",
86	    );
87	  }
88	}
89	
90	function isProjectSource(parentURL) {
91	  if (!parentURL || !parentURL.startsWith("file:")) return false;
92	  const p = fileURLToPath(parentURL).replace(/\\/g, "/");
93	  return p.startsWith(ROOT_POSIX) && !p.includes("/node_modules/");
94	}
95	
96	/** Teach Node's resolver about extensionless imports and the "@/" alias. */
97	export function registerTsResolution() {
98	  if (hooksRegistered) return;
99	  hooksRegistered = true;
100	
101	  registerHooks({
102	    resolve(specifier, context, nextResolve) {
103	      if (!isProjectSource(context.parentURL)) return nextResolve(specifier, context);
104	
105	      const parentDir = path.dirname(fileURLToPath(context.parentURL));
106	      let spec = specifier;
107	
108	      if (spec.startsWith("@/")) {
109	        const abs = path.join(ROOT, spec.slice(2));
110	        spec = "./" + path.relative(parentDir, abs).replace(/\\/g, "/");
111	      }
112	
113	      if (!spec.startsWith("./") && !spec.startsWith("../")) {
114	        return nextResolve(specifier, context);
115	      }
116	
117	      const abs = path.resolve(parentDir, spec);
118	      if (path.extname(abs) && existsSync(abs)) return nextResolve(spec, context);
119	
120	      for (const ext of CANDIDATE_EXTENSIONS) {
121	        if (existsSync(abs + ext)) return nextResolve(pathToFileURL(abs + ext).href, context);
122	      }
123	      return nextResolve(spec, context);
124	    },
125	  });
126	}
127	
128	/** Node's own type-stripping and typeless-package warnings are just noise here. */
129	export function quietNodeWarnings() {
130	  process.removeAllListeners("warning");
131	  process.on("warning", (warning) => {
132	    const name = warning.name ?? "";
133	    const code = /** @type {{ code?: string }} */ (warning).code ?? "";
134	    if (code === "MODULE_TYPELESS_PACKAGE_JSON") return;
135	    if (name === "ExperimentalWarning") return;
136	    console.warn(warning.stack ?? String(warning));
137	  });
138	}
139	
140	const importFromRoot = (rel) => import(pathToFileURL(path.join(ROOT, rel)).href);
141	
142	/**
143	 * Loads the production generation modules. Note what is NOT loaded: lib/db.ts,
144	 * lib/credits.ts and lib/events.ts all instantiate Prisma at module scope, and
145	 * the harness must never touch the application database. costMicros is
146	 * therefore re-derived from lib/models.ts's rate card in score.mjs rather than
147	 * imported from lib/credits.ts.
148	 */
149	export async function loadKodely({ quiet = false } = {}) {
150	  quietNodeWarnings();
151	  loadEnv({ quiet });
152	  registerTsResolution();
153	
154	  const [agent, buildSiteMod, foundation, models] = await Promise.all([
155	    importFromRoot("lib/agent.ts"),
156	    importFromRoot("lib/build-site.ts"),
157	    importFromRoot("lib/foundation.ts"),
158	    importFromRoot("lib/models.ts"),
159	  ]);
160	
161	  return {
162	    runAgent: agent.runAgent,
163	    normalizePath: agent.normalizePath,
164	    ENGINE: agent.ENGINE,
165	    buildSite: buildSiteMod.buildSite,
166	    BuildError: buildSiteMod.BuildError,
167	    FOUNDATION_FILES: foundation.FOUNDATION_FILES,
168	    MODELS: models.MODELS,
169	    EFFORT: models.EFFORT,
170	    MODEL_RATES: models.MODEL_RATES,
171	  };
172	}
173

1	#!/usr/bin/env node
2	// Golden-set evaluation runner.
3	//
4	//   node scripts/eval/run.mjs --only restaurant-italian
5	//   node scripts/eval/run.mjs --difficulty awkward --concurrency 2 --yes
6	//   node scripts/eval/run.mjs --list
7	//
8	// For each fixture it drives the REAL generation path — runAgent from
9	// lib/agent.ts, which dispatches to whichever engine KODELY_ENGINE selects —
10	// then compiles the result with buildSite from lib/build-site.ts, mirroring the
11	// repair loop in app/api/generate/route.ts. It records whether the site
12	// compiled first try, how many repairs it took, tokens, imputed cost, wall
13	// time, files written, and a deterministic static score, into a timestamped
14	// JSON file under scripts/eval/results/.
15	//
16	// It never touches the database. The onWrite/onDelete callbacks that the route
17	// points at Prisma are pointed at an in-memory FileMap here, and no module that
18	// instantiates a Prisma client is ever imported (see loader.mjs).
19	//
20	// EVERY RUN COSTS REAL TOKENS. The suite is ~30 first builds at `high` effort;
21	// running all of it is a deliberate act, which is why anything over
22	// CONFIRM_THRESHOLD fixtures refuses to start without --yes.
23	
24	import { mkdir, writeFile, readFile } from "node:fs/promises";
25	import { execFileSync } from "node:child_process";
26	import path from "node:path";
27	import { pathToFileURL } from "node:url";
28	import { performance } from "node:perf_hooks";
29	import { loadKodely, ROOT } from "./loader.mjs";
30	import { scoreSite, costMicros, creditsFor } from "./score.mjs";
31	
32	const EVAL_DIR = import.meta.dirname;
33	const RESULTS_DIR = path.join(EVAL_DIR, "results");
34	
35	// Mirrors MAX_BUILD_ATTEMPTS in app/api/generate/route.ts. If that changes,
36	// change it here — the harness is only honest while it repairs the same number
37	// of times production does.
38	const MAX_BUILD_ATTEMPTS = 2;
39	
40	/** Above this many fixtures, --yes is required. Generation costs real money. */
41	const CONFIRM_THRESHOLD = 5;
42	
43	const DEFAULT_TIMEOUT_MS = 10 * 60_000;
44	
45	// ── CLI ───────────────────────────────────────────────────────────────────────
46	
47	function parseArgs(argv) {
48	  const opts = {
49	    only: [],
50	    category: null,
51	    difficulty: null,
52	    limit: null,
53	    concurrency: 2,
54	    label: "run",
55	    engine: null,
56	    saveSources: false,
57	    yes: false,
58	    list: false,
59	    out: null,
60	    timeoutMs: DEFAULT_TIMEOUT_MS,
61	  };
62	  for (let i = 0; i < argv.length; i++) {
63	    const arg = argv[i];
64	    const next = () => {
65	      const v = argv[++i];
66	      if (v === undefined) throw new Error(`${arg} needs a value`);
67	      return v;
68	    };
69	    switch (arg) {
70	      case "--only": opts.only.push(...next().split(",").map((s) => s.trim()).filter(Boolean)); break;
71	      case "--category": opts.category = next(); break;
72	      case "--difficulty": opts.difficulty = next(); break;
73	      case "--limit": opts.limit = Number(next()); break;
74	      case "--concurrency": opts.concurrency = Math.max(1, Number(next())); break;
75	      case "--label": opts.label = next().replace(/[^A-Za-z0-9._-]/g, "-"); break;
76	      case "--engine": opts.engine = next(); break;
77	      case "--timeout": opts.timeoutMs = Number(next()); break;
78	      case "--out": opts.out = next(); break;
79	      case "--save-sources": opts.saveSources = true; break;
80	      case "--yes": case "-y": opts.yes = true; break;
81	      case "--list": opts.list = true; break;
82	      case "--help": case "-h": opts.help = true; break;
83	      default:
84	        throw new Error(`Unknown flag: ${arg}`);
85	    }
86	  }
87	  return opts;
88	}
89	
90	const HELP = `Kodely golden-set evaluation runner
91	
92	  node scripts/eval/run.mjs [flags]
93	
94	  --only <id[,id]>    run just these fixtures (repeatable)
95	  --category <name>   filter by fixture category (restaurant, saas, adversarial, ...)
96	  --difficulty <name> filter by difficulty (standard | awkward)
97	  --limit <n>         cap the number of fixtures after filtering
98	  --concurrency <n>   parallel generations (default 2 — these are expensive)
99	  --label <name>      goes in the result filename, e.g. --label baseline
100	  --engine <api|sdk>  override KODELY_ENGINE for this run
101	  --timeout <ms>      per-fixture wall-clock budget (default 600000)
102	  --save-sources      embed the generated source files in the result JSON
103	  --out <file>        write the result here instead of scripts/eval/results/
104	  --list              print the fixture set and exit, generating nothing
105	  -y, --yes           required to run more than ${CONFIRM_THRESHOLD} fixtures
106	
107	Compare two result files with:
108	  node scripts/eval/report.mjs <before.json> <after.json>
109	`;
110	
111	// ── helpers ───────────────────────────────────────────────────────────────────
112	
113	const fmtMs = (ms) => `${(ms / 1000).toFixed(1)}s`;
114	
115	function gitInfo() {
116	  const git = (args) => execFileSync("git", args, { cwd: ROOT, encoding: "utf8" }).trim();
117	  try {
118	    return { commit: git(["rev-parse", "--short", "HEAD"]), dirty: git(["status", "--porcelain"]).length > 0 };
119	  } catch {
120	    return { commit: null, dirty: null };
121	  }
122	}
123	
124	/** Bounded worker pool. Keeps `limit` generations in flight, in fixture order. */
125	async function pool(items, limit, worker) {
126	  const results = new Array(items.length);
127	  let cursor = 0;
128	  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
129	    while (true) {
130	      const i = cursor++;
131	      if (i >= items.length) return;
132	      results[i] = await worker(items[i], i);
133	    }
134	  });
135	  await Promise.all(runners);
136	  return results;
137	}
138	
139	// ── one fixture ───────────────────────────────────────────────────────────────
140	
141	async function runFixture(fixture, kodely, opts) {
142	  const { runAgent, normalizePath, buildSite, BuildError, FOUNDATION_FILES, MODEL_RATES } = kodely;
143	
144	  const startedAt = new Date().toISOString();
145	  const t0 = performance.now();
146	
147	  // The whole project lives here. This is what the route keeps in Prisma; the
148	  // harness keeps it in memory so a run can never write to the app database.
149	  const files = { ...FOUNDATION_FILES };
150	  const foundationPaths = new Set(Object.keys(FOUNDATION_FILES));
151	
152	  let filesWritten = 0;
153	  let repairAttempts = 0;
154	  let model = "";
155	  let reply = "";
156	  const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
157	  const writtenPaths = new Set();
158	
159	  const controller = new AbortController();
160	  const timer = setTimeout(() => controller.abort(), opts.timeoutMs);
161	
162	  let dist = null;
163	  let error = null;
164	  let buildErrors = [];
165	
166	  try {
167	    let request = fixture.prompt;
168	
169	    for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
170	      if (controller.signal.aborted) break;
171	
172	      const generator = runAgent({
173	        history: [],
174	        request,
175	        files: { ...files },
176	        // Always "create": the golden set measures first-build quality, which
177	        // is the metric the roadmap gates on. Edit-quality would be a second,
178	        // separate fixture set with a starting FileMap per entry.
179	        kind: "create",
180	        signal: controller.signal,
181	        onWrite: async (p, content) => {
182	          if (!normalizePath(p)) return false;
183	          files[p] = content;
184	          writtenPaths.add(p);
185	          filesWritten++;
186	          return true;
187	        },
188	        onDelete: async (p) => {
189	          if (!(p in files)) return false;
190	          delete files[p];
191	          return true;
192	        },
193	      });
194	
195	      for await (const event of generator) {
196	        if (event.type === "text") reply += event.text;
197	        else if (event.type === "usage") {
198	          model = event.model;
199	          totals.inputTokens += event.inputTokens;
200	          totals.outputTokens += event.outputTokens;
201	          totals.cacheReadTokens += event.cacheReadTokens;
202	          totals.cacheWriteTokens += event.cacheWriteTokens;
203	        }
204	      }
205	
206	      if (controller.signal.aborted) break;
207	
208	      try {
209	        dist = await buildSite({ ...files });
210	        break;
211	      } catch (err) {
212	        const message = err instanceof BuildError ? err.message : String(err);
213	        buildErrors.push(message);
214	        if (attempt >= MAX_BUILD_ATTEMPTS) {
215	          error = message;
216	          break;
217	        }
218	        repairAttempts++;
219	        // Verbatim from app/api/generate/route.ts — a repair prompt that
220	        // differs from production's would measure the wrong thing.
221	        request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${message}`;
222	      }
223	    }
224	
225	    if (controller.signal.aborted && !dist) {
226	      error = error ?? `Timed out after ${opts.timeoutMs}ms`;
227	    }
228	  } catch (err) {
229	    error = err?.message ?? String(err);
230	  } finally {
231	    clearTimeout(timer);
232	  }
233	
234	  const wallMs = Math.round(performance.now() - t0);
235	  const micros = costMicros(MODEL_RATES, model, totals);
236	  const scored = scoreSite({ source: files, dist, fixture, foundationPaths });
237	
238	  return {
239	    id: fixture.id,
240	    category: fixture.category,
241	    difficulty: fixture.difficulty,
242	    prompt: fixture.prompt,
243	    startedAt,
244	    ok: Boolean(dist),
245	    error,
246	    // The headline metric the roadmap gates on. `false` when the build never
247	    // compiled at all, so a total failure is never mistaken for a green build.
248	    compiledFirstTry: Boolean(dist) && repairAttempts === 0,
249	    repairAttempts,
250	    buildErrors: buildErrors.map((m) => m.slice(0, 600)),
251	    wallMs,
252	    filesWritten,
253	    filesWrittenPaths: [...writtenPaths].sort(),
254	    sourceFileCount: Object.keys(files).length,
255	    distFileCount: dist ? Object.keys(dist).length : 0,
256	    model,
257	    usage: totals,
258	    costMicros: micros,
259	    credits: creditsFor(micros),
260	    replyChars: reply.trim().length,
261	    score: scored,
262	    ...(opts.saveSources ? { source: files } : {}),
263	  };
264	}
265	
266	// ── aggregate ─────────────────────────────────────────────────────────────────
267	
268	export function aggregate(results) {
269	  const n = results.length;
270	  const sum = (fn) => results.reduce((acc, r) => acc + (fn(r) || 0), 0);
271	  const mean = (fn) => (n ? sum(fn) / n : 0);
272	  const okResults = results.filter((r) => r.ok);
273	
274	  const checkTotals = {};
275	  for (const r of results) {
276	    for (const c of r.score?.checks ?? []) {
277	      const t = (checkTotals[c.id] ??= { pass: 0, fail: 0, error: 0, skip: 0 });
278	      t[c.status] = (t[c.status] ?? 0) + 1;
279	    }
280	  }
281	
282	  return {
283	    count: n,
284	    okCount: okResults.length,
285	    okRate: n ? okResults.length / n : 0,
286	    greenFirstTryCount: results.filter((r) => r.compiledFirstTry).length,
287	    // The kill-criterion metric, over ALL fixtures — a build that never
288	    // compiled counts against it, exactly as it would for a customer.
289	    greenFirstTryRate: n ? results.filter((r) => r.compiledFirstTry).length / n : 0,
290	    meanRepairAttempts: mean((r) => r.repairAttempts),
291	    meanScore: mean((r) => r.score?.score ?? 0),
292	    meanScoreOk: okResults.length
293	      ? okResults.reduce((a, r) => a + (r.score?.score ?? 0), 0) / okResults.length
294	      : 0,
295	    meanWallMs: mean((r) => r.wallMs),
296	    totalCostMicros: sum((r) => r.costMicros),
297	    meanCostMicros: mean((r) => r.costMicros),
298	    totalCredits: sum((r) => r.credits),
299	    meanCredits: mean((r) => r.credits),
300	    totalOutputTokens: sum((r) => r.usage?.outputTokens),
301	    meanFilesWritten: mean((r) => r.filesWritten),
302	    checkTotals,
303	  };
304	}
305	
306	// ── main ──────────────────────────────────────────────────────────────────────
307	
308	async function main() {
309	  let opts;
310	  try {
311	    opts = parseArgs(process.argv.slice(2));
312	  } catch (err) {
313	    console.error(`${err.message}\n\n${HELP}`);
314	    process.exit(2);
315	  }
316	  if (opts.help) {
317	    console.log(HELP);
318	    return;
319	  }
320	
321	  const fixtureSet = JSON.parse(await readFile(path.join(EVAL_DIR, "prompts.json"), "utf8"));
322	  const all = fixtureSet.fixtures;
323	
324	  let selected = all;
325	  if (opts.only.length) {
326	    const known = new Set(all.map((f) => f.id));
327	    const missing = opts.only.filter((id) => !known.has(id));
328	    if (missing.length) {
329	      console.error(`Unknown fixture id(s): ${missing.join(", ")}`);
330	      process.exit(2);
331	    }
332	    selected = all.filter((f) => opts.only.includes(f.id));
333	  }
334	  if (opts.category) selected = selected.filter((f) => f.category === opts.category);
335	  if (opts.difficulty) selected = selected.filter((f) => f.difficulty === opts.difficulty);
336	  if (opts.limit) selected = selected.slice(0, opts.limit);
337	
338	  if (opts.list) {
339	    console.log(`${all.length} fixtures (${selected.length} selected)\n`);
340	    for (const f of selected) {
341	      const mark = f.difficulty === "awkward" ? "*" : " ";
342	      console.log(`${mark} ${f.id.padEnd(32)} ${f.category.padEnd(14)} ${f.prompt.slice(0, 70)}...`);
343	    }
344	    console.log(`\n* = deliberately awkward fixture`);
345	    return;
346	  }
347	
348	  if (!selected.length) {
349	    console.error("No fixtures matched the filters.");
350	    process.exit(2);
351	  }
352	
353	  if (selected.length > CONFIRM_THRESHOLD && !opts.yes) {
354	    console.error(
355	      `Refusing to run ${selected.length} fixtures without --yes.\n` +
356	        `Each one is a full first build against a real model. Narrow it with ` +
357	        `--only/--difficulty/--limit, or pass --yes if you mean it.`,
358	    );
359	    process.exit(2);
360	  }
361	
362	  if (opts.engine) process.env.KODELY_ENGINE = opts.engine;
363	
364	  const kodely = await loadKodely();
365	
366	  const runStartedAt = new Date();
367	  const stamp = runStartedAt.toISOString().replace(/[:.]/g, "-").replace("Z", "Z");
368	  const outPath = opts.out
369	    ? path.resolve(opts.out)
370	    : path.join(RESULTS_DIR, `${stamp}-${opts.label}.json`);
371	
372	  console.log(
373	    `[eval] ${selected.length} fixture(s), engine=${kodely.ENGINE}, ` +
374	      `builder=${kodely.MODELS.builder}, effort(create)=${kodely.EFFORT.create}, ` +
375	      `concurrency=${opts.concurrency}`,
376	  );
377	  console.log(`[eval] results -> ${outPath}\n`);
378	
379	  let done = 0;
380	  const results = await pool(selected, opts.concurrency, async (fixture) => {
381	    const result = await runFixture(fixture, kodely, opts);
382	    done++;
383	    const verdict = !result.ok
384	      ? "FAILED"
385	      : result.compiledFirstTry
386	        ? "green"
387	        : `repaired x${result.repairAttempts}`;
388	    console.log(
389	      `[${String(done).padStart(2)}/${selected.length}] ${result.id.padEnd(32)} ` +
390	        `${verdict.padEnd(13)} score ${(result.score.score * 100).toFixed(0).padStart(3)}% ` +
391	        `${String(result.score.passed)}/${result.score.applicable} checks  ` +
392	        `${fmtMs(result.wallMs).padStart(7)}  ${result.credits} cr` +
393	        (result.error ? `  :: ${result.error.split("\n")[0].slice(0, 90)}` : ""),
394	    );
395	    return result;
396	  });
397	
398	  const payload = {
399	    schemaVersion: 1,
400	    label: opts.label,
401	    startedAt: runStartedAt.toISOString(),
402	    finishedAt: new Date().toISOString(),
403	    engine: kodely.ENGINE,
404	    models: { ...kodely.MODELS },
405	    effort: { ...kodely.EFFORT },
406	    concurrency: opts.concurrency,
407	    fixtureSetVersion: fixtureSet.version,
408	    selectedIds: selected.map((f) => f.id),
409	    git: gitInfo(),
410	    node: process.version,
411	    aggregate: aggregate(results),
412	    results,
413	  };
414	
415	  await mkdir(path.dirname(outPath), { recursive: true });
416	  await writeFile(outPath, JSON.stringify(payload, null, 2), "utf8");
417	
418	  const a = payload.aggregate;
419	  console.log(
420	    `\n[eval] green-build-first-try ${(a.greenFirstTryRate * 100).toFixed(0)}% ` +
421	      `(${a.greenFirstTryCount}/${a.count})   compiled ${a.okCount}/${a.count}   ` +
422	      `mean score ${(a.meanScore * 100).toFixed(0)}%   ` +
423	      `mean ${fmtMs(a.meanWallMs)}   ${a.totalCredits} credits total`,
424	  );
425	  console.log(`[eval] wrote ${outPath}`);
426	  console.log(`[eval] compare with: node scripts/eval/report.mjs <baseline.json> ${path.relative(ROOT, outPath).replace(/\\/g, "/")}`);
427	}
428	
429	// Only run when invoked directly, so `aggregate` and `pool` can be imported
430	// (and tested) without kicking off a suite as a side effect of the import.
431	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
432	  main().catch((err) => {
433	    console.error(err);
434	    process.exit(1);
435	  });
