1	// Seeds content/seo/*.json into the BlogPost table.
2	//
3	//   node scripts/seo/seed.mjs --dry-run    what would change, writes nothing
4	//   node scripts/seo/seed.mjs              apply it
5	//
6	// Three properties this script is built around:
7	//
8	// 1. IDEMPOTENT. It diffs each article against the row already in the database
9	//    and skips anything byte-identical. Prisma's @updatedAt fires on every
10	//    `update` call regardless of whether values changed, so an unconditional
11	//    upsert would churn updatedAt on every deploy and make the column useless
12	//    as a signal of "when did this article actually change".
13	//
14	// 2. NON-DESTRUCTIVE. It only ever creates or updates rows whose slug appears
15	//    in content/seo/. Rows it does not own are reported as "not managed here"
16	//    and left completely alone — there is no delete path in this file at all.
17	//
18	// 3. VALIDATED FIRST. Nothing is written unless every article passes
19	//    scripts/seo/validate.mjs. bodyHtml goes into the page through
20	//    dangerouslySetInnerHTML, so malformed markup is not a cosmetic problem —
21	//    it breaks the layout of a live page.
22	
23	import { PrismaClient } from "@prisma/client";
24	import { loadEnv, loadArticles, toRow, ARTICLE_FIELDS } from "./lib.mjs";
25	import { validateAll } from "./validate.mjs";
26	
27	const DRY_RUN = process.argv.includes("--dry-run");
28	
29	function fieldsThatDiffer(row, existing) {
30	  return ARTICLE_FIELDS.filter((field) => row[field] !== existing[field]);
31	}
32	
33	function preview(text, max = 72) {
34	  const flat = String(text).replace(/\s+/g, " ").trim();
35	  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat;
36	}
37	
38	async function main() {
39	  loadEnv();
40	  if (!process.env.DATABASE_URL) {
41	    console.error("DATABASE_URL is not set, and .env did not provide one.");
42	    process.exit(1);
43	  }
44	
45	  const articles = loadArticles();
46	  if (articles.length === 0) {
47	    console.error("No articles found in content/seo/ — nothing to seed.");
48	    process.exit(1);
49	  }
50	
51	  const invalid = validateAll(articles).filter((r) => r.problems.length > 0);
52	  if (invalid.length > 0) {
53	    console.error(`Refusing to seed: ${invalid.length} article(s) failed validation.\n`);
54	    for (const { article, problems } of invalid) {
55	      console.error(`  ${article.file}`);
56	      for (const p of problems) console.error(`    - ${p}`);
57	    }
58	    console.error("\nRun: node scripts/seo/validate.mjs");
59	    process.exit(1);
60	  }
61	
62	  const db = new PrismaClient();
63	  const plan = { create: [], update: [], unchanged: [] };
64	
65	  try {
66	    const existingRows = await db.blogPost.findMany({
67	      select: {
68	        slug: true,
69	        title: true,
70	        metaDescription: true,
71	        category: true,
72	        targetKeyword: true,
73	        bodyHtml: true,
74	      },
75	    });
76	    const existing = new Map(existingRows.map((r) => [r.slug, r]));
77	
78	    for (const article of articles) {
79	      const row = toRow(article);
80	      const current = existing.get(row.slug);
81	      if (!current) {
82	        plan.create.push({ row });
83	      } else {
84	        const changed = fieldsThatDiffer(row, current);
85	        if (changed.length === 0) plan.unchanged.push({ row });
86	        else plan.update.push({ row, changed });
87	      }
88	    }
89	
90	    const managed = new Set(articles.map((a) => a.slug));
91	    const foreign = existingRows.filter((r) => !managed.has(r.slug));
92	
93	    // ── Report ────────────────────────────────────────────────────────────
94	    console.log(DRY_RUN ? "DRY RUN — nothing will be written.\n" : "Seeding BlogPost…\n");
95	
96	    for (const { row } of plan.create) {
97	      console.log(`  create    ${row.slug}`);
98	      console.log(`            "${preview(row.title)}"  [${row.category}]`);
99	    }
100	    for (const { row, changed } of plan.update) {
101	      console.log(`  update    ${row.slug}  (${changed.join(", ")})`);
102	      for (const field of changed) {
103	        if (field === "bodyHtml") {
104	          const before = existing.get(row.slug).bodyHtml.length;
105	          console.log(`            bodyHtml: ${before} chars -> ${row.bodyHtml.length} chars`);
106	        } else {
107	          console.log(`            ${field}: "${preview(existing.get(row.slug)[field], 40)}"`);
108	          console.log(`            ${" ".repeat(field.length)}  -> "${preview(row[field], 40)}"`);
109	        }
110	      }
111	    }
112	    for (const { row } of plan.unchanged) {
113	      console.log(`  unchanged ${row.slug}`);
114	    }
115	    for (const row of foreign) {
116	      console.log(`  skip      ${row.slug}  (in the database, not managed by content/seo/)`);
117	    }
118	
119	    // ── Apply ─────────────────────────────────────────────────────────────
120	    if (!DRY_RUN) {
121	      for (const { row } of plan.create) {
122	        // create-not-upsert on this branch is deliberate: if a row appeared
123	        // between the read above and here, that is a genuine race worth
124	        // surfacing rather than quietly overwriting someone else's write.
125	        await db.blogPost.create({ data: row });
126	      }
127	      for (const { row } of plan.update) {
128	        const { slug, ...data } = row;
129	        await db.blogPost.update({ where: { slug }, data });
130	      }
131	    }
132	
133	    console.log(
134	      `\n${plan.create.length} created, ${plan.update.length} updated, ` +
135	        `${plan.unchanged.length} unchanged, ${foreign.length} left alone.`,
136	    );
137	    if (DRY_RUN && plan.create.length + plan.update.length > 0) {
138	      console.log("Re-run without --dry-run to apply.");
139	    }
140	  } finally {
141	    await db.$disconnect();
142	  }
143	}
144	
145	main().catch((error) => {
146	  console.error(error);
147	  process.exit(1);
148	});
