1	// A minimal ZIP writer over node:zlib. The only thing Kodely zips is a project's
2	// source tree — a few dozen small UTF-8 text files — which isn't enough to
3	// justify carrying a zip dependency through every install and deploy.
4	//
5	// Deliberately NOT ZIP64: this emits the classic format, which tops out at 4 GB
6	// per entry and 65,535 entries. Source trees are nowhere near either limit; if
7	// they ever get there, reach for a real library rather than extending this.
8	
9	import { deflateRaw } from "node:zlib";
10	
11	const LOCAL_FILE_HEADER = 0x04034b50;
12	const CENTRAL_FILE_HEADER = 0x02014b50;
13	const END_OF_CENTRAL_DIR = 0x06054b50;
14	
15	// Bit 11 tells the extractor that names are UTF-8 rather than the ancient
16	// IBM code page the format otherwise assumes.
17	const FLAG_UTF8_NAMES = 0x0800;
18	
19	const METHOD_STORE = 0;
20	const METHOD_DEFLATE = 8;
21	
22	// High byte 3 = Unix, so the external attributes below are read as file mode.
23	const VERSION_MADE_BY = (3 << 8) | 20;
24	const VERSION_NEEDED = 20;
25	
26	// Regular file, rw-r--r--. Without this, extractors on Unix hand the user a
27	// tree of mode-000 files. The `>>> 0` matters: the shift alone overflows into
28	// a negative signed int32, which writeUInt32LE rejects outright.
29	const UNIX_FILE_MODE = (0o100644 << 16) >>> 0;
30	
31	const CRC_TABLE = (() => {
32	  const table = new Uint32Array(256);
33	  for (let i = 0; i < 256; i++) {
34	    let c = i;
35	    for (let bit = 0; bit < 8; bit++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
36	    table[i] = c >>> 0;
37	  }
38	  return table;
39	})();
