1	import nodemailer from "nodemailer";
2	
3	// Transactional mail for Kodely. Sends through the EXISTING Nxeon mail
4	// server (kodely.me's MX is mail.nxeon.cloud and its SPF already includes
5	// nxeon.cloud) rather than adding a third-party sender — no new vendor, no
6	// new cost, and no new domain-reputation setup, since mail leaving that host
7	// for kodely.me already passes SPF.
8	//
9	// Follows the same "inert until configured" shape as lib/stripe.ts: with no
10	// SMTP_* env vars set, isMailConfigured() is false and callers return a clean
11	// 503 instead of throwing. That keeps a fresh clone / local instance working
12	// without mail credentials, and makes "not configured" a visible state rather
13	// than a runtime crash.
14	
15	const HOST = process.env.SMTP_HOST;
16	const PORT = Number(process.env.SMTP_PORT ?? 587);
17	const USER = process.env.SMTP_USER;
18	const PASS = process.env.SMTP_PASS;
19	
20	// Envelope sender. MUST be a domain the sending server is allowed to send
21	// for, or SPF/DMARC will fail — this is not the visitor's address (see the
22	// Reply-To note in sendContactEmail).
23	const FROM = process.env.MAIL_FROM ?? "Kodely <noreply@kodely.me>";
24	export const CONTACT_TO = process.env.CONTACT_TO ?? "hello@kodely.me";
25	
26	export function isMailConfigured(): boolean {
27	  return Boolean(HOST && USER && PASS);
28	}
29	
30	let cached: nodemailer.Transporter | null = null;
31	
32	function transporter(): nodemailer.Transporter {
33	  if (!isMailConfigured()) throw new Error("SMTP is not configured");
34	  if (!cached) {
35	    cached = nodemailer.createTransport({
36	      host: HOST,
37	      port: PORT,
38	      // 465 is implicit TLS; 587 starts plaintext and upgrades via STARTTLS.
39	      secure: PORT === 465,
40	      auth: { user: USER, pass: PASS },
41	    });
42	  }
43	  return cached;
44	}
45	
46	// Strip CR/LF before any user-supplied value reaches a mail HEADER. Without
47	// this a visitor could put "\r\nBcc: victim@example.com" in the name field
48	// and turn this form into an open relay (classic SMTP header injection).
49	// Body content doesn't need this — only headers.
50	function headerSafe(value: string, max = 200): string {
51	  return value.replace(/[\r\n]+/g, " ").trim().slice(0, max);
52	}
53	
54	export async function sendContactEmail(input: {
55	  name: string;
56	  email: string;
57	  message: string;
58	}): Promise<void> {
59	  const name = headerSafe(input.name, 120);
60	  const email = headerSafe(input.email, 200);
61	  const message = input.message.slice(0, 5000);
62	
63	  await transporter().sendMail({
64	    from: FROM,
65	    to: CONTACT_TO,
66	    // Reply-To carries the visitor's address, NOT From. Sending as the
67	    // visitor's own domain would fail that domain's SPF/DMARC and get the
68	    // mail junked or rejected — but replying in a mail client still goes
69	    // straight to them, which is the behaviour actually wanted here.
70	    replyTo: `${name} <${email}>`,
71	    subject: `Kodely contact — ${name || email}`,
72	    text: `From: ${name} <${email}>\n\n${message}\n`,
73	  });
74	}
