97	async function enhanceViaApi(prompt: string, signal?: AbortSignal): Promise<string> {
98	  const { controller, release } = withDeadline(API_TIMEOUT_MS, signal);
99	  try {
100	    // No `thinking` and no `output_config.effort` here on purpose: Haiku 4.5
101	    // rejects effort, and a 220-word brief is not a reasoning problem. If
102	    // KODELY_MODEL_ENHANCER is ever pointed at a bigger model, this stays
103	    // correct — it just leaves that model on its own defaults.
104	    const message = await anthropic.messages.create(
105	      {
106	        model: MODELS.enhancer,
107	        max_tokens: 1500,
108	        // No cache_control, unlike lib/agent.ts: this system prompt is well
109	        // under the ~1k-token minimum cacheable prefix, so a breakpoint here
110	        // would be silently ignored and only mislead the next reader.
111	        system: ENHANCE_SYSTEM,
112	        messages: [{ role: "user", content: userTurn(prompt) }],
113	      },
114	      { signal: controller.signal },
115	    );
116	
117	    if (message.stop_reason === "refusal") {
118	      throw new Error("The request was declined.");
119	    }
120	
121	    return message.content
122	      .filter((block): block is Anthropic.TextBlock => block.type === "text")
123	      .map((block) => block.text)
124	      .join("")
125	      .trim();
126	  } finally {
127	    release();
128	  }
129	}
130	
131	async function enhanceViaSdk(prompt: string, signal?: AbortSignal): Promise<string> {
132	  // Imported for its module-scope side effect as much as for query():
133	  // lib/agent-sdk.ts strips ANTHROPIC_API_KEY from the environment so nothing
134	  // the SDK spawns can quietly bill the metered key on a box whose operator
135	  // asked for the subscription engine. Enhance can be the first SDK call a
136	  // process makes, so it must not skip that.
137	  await import("./agent-sdk");
138	  const { query } = await import("@anthropic-ai/claude-agent-sdk");
139	
140	  const { controller, release } = withDeadline(SDK_TIMEOUT_MS, signal);
141	  let out = "";
142	  try {
143	    for await (const message of query({
144	      prompt: userTurn(prompt),
145	      options: {
146	        systemPrompt: ENHANCE_SYSTEM,
147	        model: MODELS.enhancer,
148	        // No tools at all — this is one prompt in, one paragraph out. Combined
149	        // with a temp cwd and no filesystem settings, the agent has nothing to
150	        // read: it cannot wander into this repo or pick up its CLAUDE.md.
151	        allowedTools: [],
152	        settingSources: [],
153	        cwd: tmpdir(),
154	        maxTurns: 1,
155	        permissionMode: "dontAsk",
156	        abortController: controller,
157	      },
158	    })) {
159	      if (message.type === "assistant" && message.message?.content) {
160	        for (const block of message.message.content) {
161	          if ("text" in block && block.text) out += block.text;
162	        }
163	      }
164	    }
165	  } finally {
166	    release();
167	  }
168	
169	  if (controller.signal.aborted) throw new Error("Enhance timed out.");
170	  return out.trim();
171	}
