55	/**
56	 * Every article on disk, ordered by filename so output is stable run to run.
57	 * Throws on malformed JSON rather than silently skipping — a file that does
58	 * not parse is a bug to fix, not an article to omit.
59	 */
60	export function loadArticles(dir = CONTENT_DIR) {
61	  if (!existsSync(dir)) return [];
62	  const files = readdirSync(dir)
63	    .filter((name) => name.endsWith(".json"))
64	    .sort();
65	
66	  return files.map((name) => {
67	    const path = join(dir, name);
68	    let raw;
69	    try {
70	      raw = JSON.parse(readFileSync(path, "utf8"));
71	    } catch (error) {
72	      throw new Error(`${name}: not valid JSON — ${error.message}`);
73	    }
74	    const body = Array.isArray(raw.body) ? raw.body : [];
75	    return {
76	      file: name,
77	      expectedSlug: basename(name, ".json"),
78	      slug: raw.slug,
79	      title: raw.title,
80	      metaDescription: raw.metaDescription,
81	      category: raw.category,
82	      targetKeyword: raw.targetKeyword,
83	      body,
84	      bodyHtml: body.join("\n"),
85	    };
86	  });
87	}
