1	// Deterministic scoring of one generated site. No model call, no network.
2	//
3	// Every check here is cheap, repeatable and answers a question someone would
4	// actually ask about a shipped page. The bar for including a check was: could
5	// this fail on a real generation, and would a human agree that failing it is
6	// worse? Anything that came down to taste was left out — taste needs a judge,
7	// and a judge is a different, more expensive instrument than this one.
8	//
9	// Checks return one of:
10	//   "pass" / "fail" — counted in the score
11	//   "skip"          — not applicable to this fixture, excluded from the
12	//                     denominator (e.g. the html-lang check only runs on a
13	//                     fixture that declares an expected language)
14	//   "error"         — the input needed for the check was missing (usually
15	//                     because the build failed), counted as a fail so a broken
16	//                     build never scores well by omission.
17	
18	/** Rough guide only — see MODEL_RATES in lib/models.ts for the real card. */
19	export function costMicros(rates, model, usage) {
20	  // Deliberately duplicated from lib/credits.ts rather than imported: that
21	  // module instantiates Prisma at module scope, and this harness must never
22	  // open a connection to the application database. Keep the arithmetic in sync
23	  // with costMicros() there — MODEL_RATES is USD per MILLION tokens, which is
24	  // numerically already micro-dollars per token, so there is no /1e6.
25	  const rate = rates[model] ?? rates.default;
26	  return Math.round(
27	    rate.input * (usage.inputTokens ?? 0) +
28	      rate.output * (usage.outputTokens ?? 0) +
29	      rate.cacheRead * (usage.cacheReadTokens ?? 0) +
30	      rate.cacheWrite * (usage.cacheWriteTokens ?? 0),
31	  );
32	}
