34	/** One credit = $0.002 of model spend. Mirrors MICROS_PER_CREDIT in lib/credits.ts. */
35	export const MICROS_PER_CREDIT = 2_000;
36	// Must stay identical to creditsFor() in lib/credits.ts — this harness exists
37	// to report what a build WOULD be charged, so any divergence makes every cost
38	// figure it prints a lie. The zero case is deliberate and load-bearing: a build
39	// with no metered telemetry (common on the SDK engine) costs nothing and must
40	// therefore charge nothing.
41	export const creditsFor = (micros) =>
42	  micros <= 0 ? 0 : Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));
